import{_ as a,o as s,c as r,ag as t}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Prise en main","description":"","frontmatter":{},"headers":[],"relativePath":"fr/getting-started.md","filePath":"fr/getting-started.md"}'),n={name:"fr/getting-started.md"};function i(o,e,l,c,p,d){return s(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="prise-en-main" tabindex="-1">Prise en main <a class="header-anchor" href="#prise-en-main" aria-label="Permalink to &quot;Prise en main&quot;">​</a></h1><p>Cette page vous mène de l&#39;achat à la première ouverture du panneau de réglages en jeu. Elle est la même pour tous les scripts Nayretis.</p><h2 id="acheter-et-telecharger" tabindex="-1">Acheter et télécharger <a class="header-anchor" href="#acheter-et-telecharger" aria-label="Permalink to &quot;Acheter et télécharger&quot;">​</a></h2><ol><li>Achetez le script sur la <a href="https://www.nayretis.com" target="_blank" rel="noreferrer">boutique Nayretis</a>. Le paiement passe par Tebex.</li><li>Connectez-vous à <a href="https://portal.cfx.re" target="_blank" rel="noreferrer">Portal</a> avec le compte Cfx.re utilisé lors de l&#39;achat. Le script et <code>nay_lib</code> sont dans vos ressources accordées.</li><li>Téléchargez les deux. <code>nay_lib</code> est fourni avec chaque script Nayretis et n&#39;est jamais vendu seul.</li></ol><p>Les scripts sont protégés par l&#39;escrow Cfx : ils ne démarrent que sur un serveur dont la clé de licence appartient au compte Cfx.re propriétaire.</p><h2 id="prerequis" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequis" aria-label="Permalink to &quot;Prérequis&quot;">​</a></h2><ul><li><a href="https://github.com/overextended/oxmysql" target="_blank" rel="noreferrer">oxmysql</a>, démarré et connecté à votre base de données.</li><li>Un des frameworks pris en charge : ESX Legacy, QBCore, QBox ou ox_core. Voir <a href="/fr/bridge/">Bridge</a> pour les inventaires, targets et notifications.</li></ul><h2 id="installer" tabindex="-1">Installer <a class="header-anchor" href="#installer" aria-label="Permalink to &quot;Installer&quot;">​</a></h2><p>Copiez le dossier <code>nay_lib</code> et le dossier du script dans votre dossier <code>resources</code>. Dans <code>server.cfg</code>, démarrez-les après votre framework, votre inventaire et votre target :</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span># votre framework, votre inventaire et votre target ici</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_car_wash</span></span></code></pre></div><p><code>nay_lib</code> s&#39;installe une seule fois, quel que soit le nombre de scripts Nayretis. Gardez-le avant tous les scripts Nayretis.</p><h2 id="premier-demarrage" tabindex="-1">Premier démarrage <a class="header-anchor" href="#premier-demarrage" aria-label="Permalink to &quot;Premier démarrage&quot;">​</a></h2><p>Démarrez le serveur. Les tables de la base sont créées automatiquement, il n&#39;y a aucun fichier SQL à importer. Dans la console, vous devez voir :</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[script:nay_lib] [INFO] Bridge ready: framework=qbox inventory=ox_inventory</span></span>
<span class="line"><span>[script:nay_lib] [INFO] Ready: settings, permissions and migrations loaded</span></span></code></pre></div><p>Les noms du framework et de l&#39;inventaire correspondent à ceux de votre serveur.</p><h2 id="vous-donner-l-acces" tabindex="-1">Vous donner l&#39;accès <a class="header-anchor" href="#vous-donner-l-acces" aria-label="Permalink to &quot;Vous donner l&#39;accès&quot;">​</a></h2><p>Les réglages se modifient en jeu avec <code>/nay</code>. Donnez l&#39;accès complet au groupe admin dans <code>server.cfg</code> :</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ace group.admin nay.admin allow</span></span></code></pre></div><p>Ou donnez-le à un joueur depuis la console du serveur :</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_grant license &lt;license&gt; nay.admin</span></span></code></pre></div><p>Rejoignez ensuite le serveur et tapez <code>/nay</code>. Plus d&#39;options sur la page <a href="/fr/nay-lib/permissions">Permissions</a>.</p><h2 id="et-ensuite" tabindex="-1">Et ensuite <a class="header-anchor" href="#et-ensuite" aria-label="Permalink to &quot;Et ensuite&quot;">​</a></h2><ul><li>Découvrez le <a href="/fr/nay-lib/panel">panneau /nay</a> : langues, thème, permissions, API et webhooks.</li><li>Configurez <a href="/fr/car-wash/">Car Wash</a>.</li><li>Quelque chose ne démarre pas ? Lisez la <a href="/fr/faq">FAQ</a>.</li></ul>`,23)])])}const g=a(n,[["render",i]]);export{h as __pageData,g as default};
